Lemma rmrep_meta_set_avail : forall st m g v,
  rmrep st m -> meta_slot st g -> 0 <= v < 2^32 ->
  rmrep (upd_meta g (m_set_avail v) st) (write_to_mem m (wa (conc st g + 24)) (le4 (wz v))).
Proof.
